import duckdb
con=duckdb.connect()
f='/tmp/claude-0/-home-user/0c78c19d-a421-5334-ba23-0ecb47664dcc/scratchpad/d08raw/ov_jp_lodging.parquet'
con.execute(f"CREATE VIEW v AS SELECT * FROM read_parquet('{f}')")
print('country', con.execute("SELECT addresses[1].country c, count(*) n FROM v GROUP BY 1 ORDER BY 2 DESC LIMIT 6").fetchall())
con.execute("CREATE VIEW jp AS SELECT * FROM v WHERE addresses[1].country='JP'")
print('JP total', con.execute("SELECT count(*) FROM jp").fetchall())
print('basic', con.execute("SELECT basic_category, count(*) FROM jp GROUP BY 1 ORDER BY 2 DESC LIMIT 15").fetchall())
print('primary', con.execute("SELECT taxonomy.primary, count(*) FROM jp GROUP BY 1 ORDER BY 2 DESC LIMIT 20").fetchall())
print('opstatus', con.execute("SELECT operating_status, count(*) FROM jp GROUP BY 1 ORDER BY 2 DESC").fetchall())
print('conf buckets', con.execute("SELECT CASE WHEN confidence IS NULL THEN 'null' WHEN confidence>=0.77 THEN '>=0.77' WHEN confidence>=0.5 THEN '0.5-0.77' ELSE '<0.5' END b, count(*) FROM jp GROUP BY 1 ORDER BY 1").fetchall())
print('common name langs', con.execute("SELECT k, count(*) FROM (SELECT unnest(map_keys(names.common)) k FROM jp) GROUP BY 1 ORDER BY 2 DESC LIMIT 10").fetchall())
print('has ko/en', con.execute("SELECT count(*) FILTER (WHERE names.common['ko'] IS NOT NULL), count(*) FILTER (WHERE names.common['en'] IS NOT NULL), count(*) FILTER (WHERE len(websites)>0), count(*) FILTER (WHERE len(phones)>0) FROM jp").fetchall())
print('providers', con.execute("SELECT s.dataset, s.license, count(*) FROM (SELECT unnest(sources) s FROM jp) GROUP BY 1,2 ORDER BY 3 DESC LIMIT 12").fetchall())
print('primary source (first)', con.execute("SELECT sources[1].dataset, count(*) FROM jp GROUP BY 1 ORDER BY 2 DESC").fetchall())
print('rules langs', con.execute("SELECT r.language, count(*) FROM (SELECT unnest(names.rules) r FROM jp) GROUP BY 1 ORDER BY 2 DESC LIMIT 8").fetchall())
print('sample', con.execute("SELECT names.primary, basic_category, taxonomy.primary, confidence, operating_status, addresses[1].freeform, addresses[1].region FROM jp WHERE addresses[1].region IN ('大分県','Oita') OR addresses[1].freeform LIKE '%湯布院%' LIMIT 12").fetchall())
print('yufuin count', con.execute("SELECT count(*), count(*) FILTER (WHERE confidence>=0.77) FROM jp WHERE bbox.xmin BETWEEN 131.30 AND 131.42 AND bbox.ymin BETWEEN 33.22 AND 33.32").fetchall())
print('region top', con.execute("SELECT addresses[1].region, count(*) FROM jp GROUP BY 1 ORDER BY 2 DESC LIMIT 8").fetchall())
